const catalog = [
  { id: "SKU-01", name: "AWS GPU Instance Monthly Credit", price_usd: 45, vendor: "Amazon Web Services" },
  { id: "SKU-02", name: "OpenAI API Enterprise Top-Up", price_usd: 100, vendor: "OpenAI" },
  { id: "SKU-03", name: "Domain & SSL Annual Renewal", price_usd: 15, vendor: "Cloudflare" }
];
return JSON.stringify(catalog);

const catalog = [
  { name: 'AWS GPU Instance Monthly Credit', price: 45, vendor: 'Amazon Web Services' },
  { name: 'OpenAI API Enterprise Top-Up', price: 100, vendor: 'OpenAI' },
  { name: 'Domain & SSL Annual Renewal', price: 15, vendor: 'Cloudflare' }
];
function parse(raw) {
  try {
    const s = String(raw || '');
    const a = s.indexOf('{');
    const b = s.lastIndexOf('}');
    return JSON.parse(a >= 0 ? s.slice(a, b + 1) : s);
  } catch (e) { return null; }
}
const requestText = String($('When chat message received').first().json.chatInput || '');
const pay = parse($('Payment Agent').first().json.output) || {};
const rev = parse($input.first().json.output) || {};
const cat = catalog.find(function (c) { return c.name === pay.item_name; });
let qty = parseInt(pay.quantity, 10);
if (!(qty >= 1)) qty = 1;
if (qty > 100) qty = 100;
let ok = false;
let blockMessage = '';
let total = 0;
if (!cat) {
  blockMessage = 'No approved catalog item matched this request, so no payment was prepared. ' + String(pay.reply || '');
} else {
  total = cat.price * qty;
  const budget = (pay.budget_usd === null || pay.budget_usd === undefined || pay.budget_usd === '') ? null : Number(pay.budget_usd);
  if (budget !== null && !isNaN(budget) && total > budget) {
    blockMessage = 'The total of $' + total + ' exceeds your stated budget of $' + budget + '. No payment was prepared.';
  } else if (pay.status !== 'NEEDS_APPROVAL') {
    blockMessage = String(pay.reply || 'The Payment Agent did not propose a payment.');
  } else if (String(rev.decision || '').toUpperCase() !== 'ESCALATE') {
    blockMessage = 'The Reviewer Agent rejected this payment: ' + String(rev.reason || 'unsafe or inconsistent request') + ' No money moved.';
  } else {
    ok = true;
  }
}
const code = String(Math.floor(1000 + Math.random() * 9000));
const reason = String(rev.reason || '').slice(0, 110);
const smsText = ok
  ? 'Spend Guard approval ' + code + ': ' + qty + ' x ' + cat.name + ' (' + cat.vendor + ') = $' + total + '. Reviewer: ' + reason + ' Reply YES ' + code + ' to approve or NO ' + code + ' to deny.'
  : '';
return [{ json: {
  ok: ok,
  code: code,
  item_name: cat ? cat.name : '',
  vendor: cat ? cat.vendor : '',
  quantity: qty,
  amount_usd: total,
  request_text: requestText,
  reviewer_decision: String(rev.decision || ''),
  reviewer_reason: reason,
  reviewer_risk: String(rev.risk || ''),
  sms_text: smsText,
  block_message: blockMessage
} }];

